contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 value) public {
        require(spender != address(0));
        require(value > 0);

        // First approval of a nonzero value succeeds and sets the allowance.
        bool ok1 = c.approve(spender, value);
        uint256 a1 = c.allowance(address(this), spender);

        // Second approval of any nonzero value while allowance is nonzero returns false
        // and leaves the allowance unchanged.
        bool ok2 = c.approve(spender, value + 1);
        uint256 a2 = c.allowance(address(this), spender);

        assert(ok1 && a1 == value && !ok2 && a2 == value);
    }

    receive() external payable {}
}

